const items = $input.all();

const cleanedRecords = [];

for (const item of items) {
  try {
    let raw = item.json.output ?? item.json.text ?? item.json;

    // Parse JSON if AI returned a string
    if (typeof raw === "string") {
      raw = raw.trim();

      // Remove Markdown code fences
      raw = raw.replace(/^```(?:json)?\s*/i, "")
               .replace(/\s*```$/, "");

      raw = JSON.parse(raw);
    }

    // Handle multiple records inside an array
    const records = Array.isArray(raw) ? raw : [raw];

    for (const student of records) {
      const errors = [];

      const clean = {
        Student_ID: String(student.Student_ID ?? "").trim(),
        Name: String(student.Name ?? "").trim(),
        Email: String(student.Email ?? "").trim().toLowerCase(),
        Phone: String(student.Phone ?? "").replace(/\D/g, ""),
        Course: String(student.Course ?? "").trim(),
        Fee_Paid: student.Fee_Paid === true ||
                  String(student.Fee_Paid).toLowerCase() === "true",
        City: String(student.City ?? "").trim(),
        Enrolled_Date: String(student.Enrolled_Date ?? "").trim()
      };

      // Required field validation
      for (const field of [
        "Student_ID", "Name", "Email",
        "Phone", "Course", "City", "Enrolled_Date"
      ]) {
        if (!clean[field]) {
          errors.push(`${field} is missing`);
        }
      }

      // Email validation
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

      if (clean.Email && !emailRegex.test(clean.Email)) {
        errors.push("Invalid email address");
      }

      // Phone validation (10 digits)
      if (clean.Phone && !/^\d{10}$/.test(clean.Phone)) {
        errors.push("Invalid phone number");
      }

      // Date validation (YYYY-MM-DD)
      const dateRegex = /^\d{4}-\d{2}-\d{2}$/;

      if (
        !dateRegex.test(clean.Enrolled_Date) ||
        isNaN(Date.parse(clean.Enrolled_Date)) ||
        new Date(clean.Enrolled_Date).toISOString().slice(0, 10)
          !== clean.Enrolled_Date
      ) {
        errors.push("Invalid enrollment date");
      }

      cleanedRecords.push({
        json: {
          ...clean,
          Validation_Status: errors.length ? "Invalid" : "Valid",
          Error_Message: errors.join("; ")
        }
      });
    }

  } catch (error) {
    cleanedRecords.push({
      json: {
        Validation_Status: "Parsing Error",
        Error_Message: error.message
      }
    });
  }
}

return cleanedRecords;
